INSERT INTO public.showcase_templates (website_id, organization_id, slug, name, url, domain, category_en, category_fr, tagline_en, tagline_fr, description_en, description_fr, features_en, features_fr, desktop_image, mobile_image, layout, animation, accent, featured_on_home, sort_order, status)
