  ('missbeauty', 'Miss Beauty', 'https://missbeauty.levelup-ecosystem.com/', 'missbeauty.levelup-ecosystem.com', 'Hair atelier & beauty', 'Atelier coiffure et beauté', 'Your hair. Your signature.', 'Your hair. Your signature.', 'A light, editorial site for a hair atelier: braids, silk press and colouring, presented like a magazine, with booking built in.', 'Un site clair et éditorial pour un atelier de coiffure : tresses, silk press et coloration présentés comme un magazine, avec la réservation intégrée.', ARRAY['Online booking', 'Service menu', 'Editorial serif design']::text[], ARRAY['Réservation en ligne', 'Carte des prestations', 'Design éditorial à empattements']::text[], 'https://levelup-ecosystem.com/home/tpl-missbeauty-desktop-1440.webp', 'https://levelup-ecosystem.com/home/tpl-missbeauty-mobile.webp', 'band', 'tilt', 'auto', true, 10, 'published'),
  ('resto', 'Taste of Egypt Cafe', 'https://resto.levelup-ecosystem.com/', 'resto.levelup-ecosystem.com', 'Café & artisanal bakery', 'Café et boulangerie artisanale', 'Haute Egyptian gastronomy', 'Haute gastronomie égyptienne', 'A dark burgundy and gold site for a luxury café and bakery: the full menu, a custom sandwich builder, a gallery and table reservations.', 'Un site bordeaux et or pour un café-boulangerie de luxe : la carte complète, un sandwich sur mesure, une galerie et la réservation de table.', ARRAY['Table reservation', 'Menu & custom sandwich', 'Photo gallery']::text[], ARRAY['Réservation de table', 'Carte et sandwich sur mesure', 'Galerie photo']::text[], 'https://levelup-ecosystem.com/home/tpl-resto-desktop-1440.webp', 'https://levelup-ecosystem.com/home/tpl-resto-mobile.webp', 'band', 'tilt', 'auto', true, 20, 'published'),
  ('travel', 'LevelFlight', 'https://travel.levelup-ecosystem.com/', 'travel.levelup-ecosystem.com', 'Travel & visa advisory', 'Voyage et conseil en visas', 'Travel, elevated.', 'Travel, elevated.', 'A cinematic navy and gold site for international travel and consular visa advice: destinations, visa services and consultation booking.', 'Un site cinématographique bleu nuit et or pour le voyage international et le conseil consulaire : destinations, services de visa et prise de rendez-vous.', ARRAY['Consultation booking', 'Destinations & visa services', 'Cinematic design']::text[], ARRAY['Prise de rendez-vous', 'Destinations et visas', 'Design cinématographique']::text[], 'https://levelup-ecosystem.com/home/tpl-travel-desktop-1440.webp', 'https://levelup-ecosystem.com/home/tpl-travel-mobile.webp', 'band', 'tilt', 'auto', true, 30, 'published')
) AS v (slug, name, url, domain, category_en, category_fr, tagline_en, tagline_fr, description_en, description_fr, features_en, features_fr, desktop_image, mobile_image, layout, animation, accent, featured_on_home, sort_order, status)
