INSERT INTO public.showcase_projects (website_id, organization_id, slug, name, url, domain, label_en, label_fr, industry_en, industry_fr, location_en, location_fr, year, project_status_en, project_status_fr, scope_en, scope_fr, summary_en, summary_fr, what_we_built_en, what_we_built_fr, tags_en, tags_fr, card_title, card_badge_en, card_description_en, card_cta_en, cover_image, desktop_image, mobile_image, gallery_images, image_alt_en, image_alt_fr, mobile_alt_en, mobile_alt_fr, gallery_captions_en, gallery_captions_fr, featured_on_home, layout, animation, accent, sort_order, status)
