te on a phone', 'Site de Final Stop Barbershop sur téléphone', ARRAY['Final Stop Barbershop website, wide view']::text[], ARRAY['Site de Final Stop Barbershop, vue large']::text[], true, 'spotlight', 'tilt', 'auto', 10, 'published'),
  ('wedding-invitation', 'Wedding Invitation', '/projects/wedding-invitation', 'levelup-ecosystem.com', 'Wedding · Digital invitation', 'Mariage · Invitation numérique', 'Wedding and private event', 'Mariage et événement privé', 'San Diego, California', 'San Diego, Californie', '2026', 'Live', 'En ligne', 'Digital invitation and online RSVP', 'Invitation numérique et RSVP en ligne', 'A digital wedding invitation with online RSVP: guests confirm in a few taps and receive their invitation card and guest number by e-mail.', 'Une invitation de mariage numérique avec réponse en ligne (RSVP) : les invités confirment en quelques gestes et reçoivent par e-mail leur carte d’invitation et leur numéro d’invité.', ARRAY['A digital invitation in the couple’s style', 'Online RSVP, saved straight to the guest list', 'Automatic confirmation e-mail with the invitation card', 'A personal guest number for each guest', 'Venue, time and dress code at a glance']::text[], ARRAY['Une invitation numérique à l’image des mariés', 'RSVP en ligne, enregistré directement dans la liste des invités', 'E-mail de confirmation automatique avec la carte d’invitation', 'Un numéro d’invité personnel pour chaque invité', 'Lieu, horaire et code vestimentaire en un coup d’œil']::text[], '{}'::text[], '{}'::text[], 'Wedding Invitation', 'Client Project • Digital Experience', 'A bespoke digital experience crafted to celebrate an unforgettable union: interactive prestige invitation, real-time online RSVP management, ceremony & reception itinerary, and automatic confirmation.', 'Explore the invitation', 'https://levelup-ecosystem.com/projects/wedding-card.jpg', 'https://levelup-ecosystem.com/projects/wedding-desktop-1440.webp', 'https://levelup-ecosystem.com/projects/wedding-mobile-long.webp', ARRAY['https://levelup-ecosystem.com/projects/wedding-card.jpg']::text[], 'Wedding invitation, opening screen on desktop', 'Invitation de mariage, écran d’ouverture sur ordinateur', 'Wedding invitation and RSVP form on a phone', 'Invitation de mariage et formulaire RSVP sur téléphone', ARRAY['Photo from the wedding invitation']::text[], ARRAY['Photo de l’invitation de mariage']::text[], false, 'spotlight', 'tilt', 'auto', 20, 'published'),
  ('blackpater', 'Black Pater', 'https://blackpater.com', 'blackpater.com', 'Personal brand & portfolio', 'Marque personnelle et portfolio', 'Personal brand and portfolio', 'Marque personnelle et portfolio', 'United States', 'États-Unis', '2026', 'Live', 'En ligne', 'Portfolio design and build, English and French', 'Conception et développement du portfolio, en anglais et en français', 'A cinematic portfolio for educator and entrepreneur Jean-Pierre Lofumbwa: editorial typography, a journey timeline, and English and French versions.', 'Un portfolio cinématographique pour l’éducateur et entrepreneur Jean-Pierre Lofumbwa : typographie éditoriale, frise de parcours, et versions anglaise et française.', ARRAY['Cinematic, editorial design', 'Custom typography', 'Interactive journey timeline', 'Cover flow showcase', 'English and French versions']::text[], ARRAY['Design cinématographique et éditorial', 'Typographie sur mesure', 'Frise de parcours interactive', 'Vitrine en « cover flow »', 'Versions anglaise et française']::text[], ARRAY['Portfolio', 'Bilingual EN/FR', 'Editorial design']::text[], ARRAY['Portfolio', 'Bilingue EN/FR', 'Design éditorial']::text[], 'Black_Pater — Portfolio', 'Client Case Study • Personal Brand & Portfolio', 'A bespoke cinematic digital portfolio designed for Jean-Pierre Lofumbwa (« Le Prof »), Congolese educator, entrepreneur, and cultural ambassador in the US. Features custom typography, interactive timeline journey, cover flow showcase, and multi-language support.', 'Visit site', 'https://i.ibb.co/S4XSRHVc/IMG-8467.jpg', 'https://levelup-ecosystem.com/home/blackpater-desktop-1440.webp', 'https://levelup-ecosystem.com/home/blackpater-mobile-long.webp', ARRAY['https://levelup-ecosystem.com/projects/blackpater-card.jpg']::text[], 'Black Pater website, home page on desktop', 'Site de Black Pater, page d’accueil sur ordinateur', 'Black Pater website on a phone', 'Site de Black Pater sur téléphone', ARRAY['Black Pater website, portrait banner']::text[], ARRAY['Site de Black Pater, bannière portrait']::text[], true, 'spotlight', 'tilt', 'auto', 30, 'published')
) AS v (slug, name, url, domain, label_en, label_fr, industry_en, industry_fr, location_en, location_fr, year, project_status_en, project_status_fr, scope_en, scope_fr, summary_en, summary_fr, what_we_built_en, what_we_built_fr, tags_en, tags_fr, card_title, card_badge_en, card_description_en, card_cta_en, cover_image, desktop_image, mobile_image, gallery_images, image_alt_en, image_alt_fr, mobile_alt_en, mobile_alt_fr, gallery_captions_en, gallery_captions_fr, featured_on_home, layout, animation, accent, sort_order, status)
